mapper.select:
 SELECT num,
		member_num, target_num, type, category, content, status, created_date, row_num FROM
		(SELECT num, member_num, target_num, type, category, content, status, created_date,
		ROW_NUMBER() OVER(ORDER BY num desc) AS row_num FROM report 




						type LIKE '%' || #{searchValue} || '%'



						category LIKE '%' || #{searchValue} || '%'



						status = #{searchValue}




		) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}
